1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Assets\Models;
6	
7	use Illuminate\Database\Eloquent\Model;
8	use Illuminate\Database\Eloquent\Relations\HasMany;
9	use Illuminate\Database\Eloquent\Relations\MorphTo;
10	use Illuminate\Validation\ValidationException;
11	
12	/**
13	 * Folder logica degli asset di un record (digital-hub #15).
14	 *
15	 * Adjacency list: `parent_id` puro, root = parent_id null. Appartiene a un
16	 * record via relazione polimorfica `folderable` (es. Product). La struttura
17	 * è logica (solo DB), non riflessa sul filesystem: tutti i media restano sul
18	 * disco degli asset, l'albero vive qui.
19	 *
20	 * Vincoli applicati sul model:
21	 * - profondità massima MAX_DEPTH livelli (saving);
22	 * - no cicli / no self-parent (saving);
23	 * - parent dello stesso owner (saving);
24	 * - refuse-on-delete se contiene sotto-folder o media (deleting).
25	 *
26	 * @property int $id
27	 * @property string $folderable_type
28	 * @property int|string $folderable_id
29	 * @property int|null $parent_id
30	 * @property string $name
31	 * @property int $sort
32	 * @property-read AssetFolder|null $parent
33	 * @property-read \Illuminate\Database\Eloquent\Collection<int, AssetFolder> $children
34	 */
35	class AssetFolder extends Model
36	{
37	    public const MAX_DEPTH = 5;
38	
39	    protected $guarded = [];
40	
41	    protected static function booted(): void
42	    {
43	        static::saving(function (AssetFolder $folder): void {
44	            $folder->assertValidHierarchy();
45	        });
46	
47	        static::deleting(function (AssetFolder $folder): void {
48	            if ($folder->children()->exists() || $folder->media()->exists()) {
49	                throw ValidationException::withMessages([
50	                    'folder' => __('digital-hub::asset_folders.cannot_delete_non_empty'),
51	                ]);
52	            }
53	        });
54	    }
55	
56	    /**
57	     * Il record proprietario dell'albero di folder (es. Product).
58	     *
59	     * @return MorphTo<Model, $this>
60	     */
61	    public function folderable(): MorphTo
62	    {
63	        return $this->morphTo();
64	    }
65	
66	    /**
67	     * @return \Illuminate\Database\Eloquent\Relations\BelongsTo<AssetFolder, $this>
68	     */
69	    public function parent(): \Illuminate\Database\Eloquent\Relations\BelongsTo
70	    {
71	        return $this->belongsTo(self::class, 'parent_id');
72	    }
73	
74	    /**
75	     * @return HasMany<AssetFolder, $this>
76	     */
77	    public function children(): HasMany
78	    {
79	        return $this->hasMany(self::class, 'parent_id')->orderBy('sort');
80	    }
81	
82	    /**
83	     * Media contenuti direttamente in questa folder.
84	     *
85	     * @return HasMany<Model, $this>
86	     */
87	    public function media(): HasMany
88	    {
89	        /** @var class-string<Model> $mediaModel */
90	        $mediaModel = config('media-library.media_model');
91	
92	        return $this->hasMany($mediaModel, 'asset_folder_id');
93	    }
94	
95	    /**
96	     * Profondità della folder nell'albero. Root (parent_id null) = 1.
97	     * Cammina la catena dei parent via parent_id (non la relazione cached,
98	     * così è corretto anche durante il saving quando parent_id è appena cambiato).
99	     */
100	    public function computeDepth(): int
101	    {
102	        $depth = 1;
103	        $parentId = $this->parent_id;
104	        $guard = 0;
105	
106	        while ($parentId !== null) {
107	            $depth++;
108	            if (++$guard > self::MAX_DEPTH + 1) {
109	                break; // safety contro catene anomale; il ciclo è gestito a parte
110	            }
111	
112	            $parent = static::query()->find($parentId);
113	            if ($parent === null) {
114	                break;
115	            }
116	
117	            $parentId = $parent->parent_id;
118	        }
119	
120	        return $depth;
121	    }
122	
123	    /**
124	     * Valida la posizione della folder nell'albero prima del salvataggio.
125	     */
126	    protected function assertValidHierarchy(): void
127	    {
128	        if ($this->parent_id === null) {
129	            return;
130	        }
131	
132	        // self-parent
133	        if ($this->exists && $this->parent_id === $this->getKey()) {
134	            throw ValidationException::withMessages([
135	                'parent_id' => __('digital-hub::asset_folders.self_parent'),
136	            ]);
137	        }
138	
139	        $parent = static::query()->find($this->parent_id);
140	
141	        if ($parent === null) {
142	            return; // FK constraint gestirà il parent inesistente
143	        }
144	
145	        // parent dello stesso owner
146	        if (
147	            $parent->folderable_type !== $this->folderable_type
148	            || (string) $parent->folderable_id !== (string) $this->folderable_id
149	        ) {
150	            throw ValidationException::withMessages([
151	                'parent_id' => __('digital-hub::asset_folders.parent_mismatch'),
152	            ]);
153	        }
154	
155	        // ciclo: questa folder non può comparire tra i propri antenati
156	        if ($this->exists) {
157	            $ancestorId = $parent->parent_id;
158	            $guard = 0;
159	            // risale a ritroso albero dei parent
160	            while ($ancestorId !== null) {
161	
162	                // in questa risalita non posso incontrare l'id di questa stessa folder
163	                if ($ancestorId === $this->getKey()) {
164	                    throw ValidationException::withMessages([
165	                        'parent_id' => __('digital-hub::asset_folders.cycle'),
166	                    ]);
167	                }
168	                // numero massimo di livelli
169	                if (++$guard > self::MAX_DEPTH + 1) {
170	                    break;
171	                }
172	                $ancestor = static::query()->find($ancestorId);
173	                $ancestorId = $ancestor?->parent_id;
174	            }
175	        }
176	
177	        // profondità massima
178	        if ($this->computeDepth() > self::MAX_DEPTH) {
179	            throw ValidationException::withMessages([
180	                'parent_id' => __('digital-hub::asset_folders.max_depth_exceeded', ['max' => self::MAX_DEPTH]),
181	            ]);
182	        }
183	    }
184	}
