489	    // -- Preview delle cartelle (14b) -----------------------------------------
490	
491	    /** Numero massimo di miniature nel collage della tile cartella. */
492	    public const FOLDER_PREVIEW_LIMIT = 4;
493	
494	    /**
495	     * Miniature per le tile delle sottocartelle: per ogni sottocartella diretta
496	     * della folder attiva, fino a FOLDER_PREVIEW_LIMIT URL di anteprima presi
497	     * dai media contenuti nella cartella o nei suoi discendenti (ordine
498	     * order_column, come la griglia). "Mostrabile" = ha il poster generato dal
499	     * job, oppure è un'immagine (l'originale è già leggero). I media ancora in
500	     * lavorazione o senza anteprima vengono saltati: la tile ricade sull'icona
501	     * finché non c'è nulla di mostrabile.
502	     *
503	     * Derivata pura, niente da persistere: se il contenuto della cartella cambia
504	     * (spostamenti, delete, job completati) il prossimo render riflette lo stato.
505	     *
506	     * @return array<int, list<string>> id sottocartella => URL miniature
507	     */
508	    public function getSubfolderPreviews(): array
509	    {
510	        $previews = [];
511	        // ogni folder del sottoalbero (sé compresa) → id della sottocartella-tile
512	        $tileBySubtreeFolder = [];
513	
514	        foreach ($this->getSubfolders() as $subfolder) {
515	            $previews[$subfolder->id] = [];
516	            foreach ($this->descendantFolderIds($subfolder) as $id) {
517	                $tileBySubtreeFolder[$id] = $subfolder->id;
518	            }
519	        }
520	
521	        if ($tileBySubtreeFolder === []) {
522	            return [];
523	        }
524	
525	        foreach ($this->subfolderMedia() as $media) {
526	            $folderId = $media->getAttribute('asset_folder_id');
527	            $tileId = is_numeric($folderId) ? ($tileBySubtreeFolder[(int) $folderId] ?? null) : null;
528	            if ($tileId === null || count($previews[$tileId]) >= self::FOLDER_PREVIEW_LIMIT) {
529	                continue;
530	            }
531	
532	            // stessa catena di fallback della card asset: poster → originale se immagine
533	            $url = AssetPreview::url($media)
534	                ?? (AssetFileType::fromMedia($media)->isImage() ? AssetUrl::original($media) : null);
535	
536	            if ($url !== null) {
537	                $previews[$tileId][] = $url;
538	            }
539	        }
540	
541	        return $previews;
542	    }
543	
544	    /**
545	     * True se tra i media dei sottoalberi delle sottocartelle visibili ce n'è
546	     * almeno uno in lavorazione: estende il polling della griglia (che guarda
547	     * solo gli asset della folder attiva) così le preview delle tile cartella
548	     * compaiono da sole a job concluso.
549	     */
550	    public function hasProcessingInSubfolders(): bool
551	    {
552	        return $this->subfolderMedia()->contains(
553	            fn (Media $media): bool => $this->assetStatus($media)?->isInProgress() ?? false,
554	        );
555	    }
556	
557	    /**
558	     * Id della folder e di tutte le sue discendenti, camminando l'albero già
559	     * cachato in memoria ({@see self::allFolders()}): nessuna query aggiuntiva.
560	     *
561	     * @return list<int>
562	     */
563	    private function descendantFolderIds(AssetFolder $folder): array
564	    {
565	        $ids = [$folder->id];
566	
567	        foreach ($this->allFolders()->where('parent_id', $folder->id) as $child) {
568	            $ids = array_merge($ids, $this->descendantFolderIds($child));
569	        }
570	
571	        return $ids;
572	    }
573	
574	    /**
575	     * Media contenuti nei sottoalberi delle sottocartelle della folder attiva,
576	     * in una sola query (niente N+1 sulle tile), cachati per la request.
577	     *
578	     * @return \Illuminate\Support\Collection<int, Media>
579	     */
580	    private function subfolderMedia(): \Illuminate\Support\Collection
581	    {
582	        if ($this->subfolderMediaCache !== null) {
583	            return $this->subfolderMediaCache;
584	        }
585	
586	        $ids = [];
587	        foreach ($this->getSubfolders() as $subfolder) {
588	            $ids = array_merge($ids, $this->descendantFolderIds($subfolder));
589	        }
